"""A small PTY-backed interactive terminal.

The terminal deliberately uses a real pseudo-terminal rather than pipes.  This is
important for programs which change their behaviour when attached to a tty (and
for bash line editing, job control, and signal-generating control characters).
"""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import select
import signal
import subprocess
import sys
import termios
import threading
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """Run an interactive bash shell connected to a pseudo-terminal.

    ``send_keystrokes`` writes exactly the supplied string to the shell's tty.
    Thus ``"\\x03"`` is handled by the tty line discipline as Ctrl-C, rather
    than being interpreted as text by the shell.  Output is copied to stdout
    and retained in :attr:`output` (and can be consumed with
    :meth:`read_output`).
    """

    def __init__(self, *, cwd: Optional[str] = None,
                 env: Optional[dict[str, str]] = None,
                 shell: str = "/bin/bash") -> None:
        self._master, slave = pty.openpty()
        self._output = bytearray()
        self._output_lock = threading.Lock()
        self._read_condition = threading.Condition(self._output_lock)
        self._closed = False
        self._eof = False

        # Make the slave the child's controlling terminal and retain the normal
        # inherited environment.  In particular, don't use --noprofile or
        # --norc: an interactive bash should source ~/.bashrc and profile files
        # in the same circumstances as a normal terminal shell.
        def child_setup() -> None:
            os.setsid()
            fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
            os.dup2(slave, 0)
            os.dup2(slave, 1)
            os.dup2(slave, 2)
            if slave > 2:
                os.close(slave)

        child_env = os.environ.copy()
        if env:
            child_env.update(env)
        try:
            self._process = subprocess.Popen(
                [shell, "-i"], stdin=slave, stdout=slave, stderr=slave,
                cwd=cwd, env=child_env, preexec_fn=child_setup,
                close_fds=True,
            )
        except Exception:
            os.close(self._master)
            os.close(slave)
            raise
        finally:
            # The parent must not hold the slave open, or EOF and job-control
            # behaviour will be wrong.
            try:
                os.close(slave)
            except OSError:
                pass

        self._reader = threading.Thread(target=self._drain, name="headless-terminal-reader",
                                        daemon=True)
        self._reader.start()

    def _drain(self) -> None:
        while True:
            try:
                ready, _, _ = select.select([self._master], [], [], 0.25)
                if not ready:
                    if self._process.poll() is not None:
                        # Drain any bytes already queued before declaring EOF.
                        try:
                            data = os.read(self._master, 65536)
                        except OSError:
                            data = b""
                        if not data:
                            break
                    continue
                data = os.read(self._master, 65536)
                if not data:
                    break
            except OSError as exc:
                if exc.errno == errno.EIO:  # Linux PTY EOF
                    break
                if exc.errno == errno.EINTR:
                    continue
                break
            with self._read_condition:
                self._output.extend(data)
                self._read_condition.notify_all()
            try:
                sys.stdout.buffer.write(data)
                sys.stdout.buffer.flush()
            except (AttributeError, OSError, BrokenPipeError):
                pass
        with self._read_condition:
            self._eof = True
            self._read_condition.notify_all()

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        if not isinstance(keystrokes, str):
            raise TypeError("keystrokes must be a string")
        if wait_sec < 0:
            raise ValueError("wait_sec must not be negative")
        payload = keystrokes.encode("utf-8")
        view = memoryview(payload)
        while view:
            if self._closed:
                raise RuntimeError("terminal is closed")
            try:
                written = os.write(self._master, view)
                view = view[written:]
            except OSError as exc:
                if exc.errno == errno.EINTR:
                    continue
                raise RuntimeError("terminal is no longer available") from exc
        if wait_sec:
            time.sleep(wait_sec)

    @property
    def output(self) -> str:
        """Return all output received so far, decoded losslessly enough for text."""
        with self._output_lock:
            return bytes(self._output).decode("utf-8", errors="replace")

    def read_output(self, wait_sec: float = 0.0) -> str:
        """Wait briefly for output and return the output received so far."""
        if wait_sec < 0:
            raise ValueError("wait_sec must not be negative")
        with self._read_condition:
            if wait_sec:
                self._read_condition.wait(timeout=wait_sec)
            return bytes(self._output).decode("utf-8", errors="replace")

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        try:
            os.close(self._master)
        except OSError:
            pass
        if self._process.poll() is None:
            try:
                self._process.terminate()
                self._process.wait(timeout=1)
            except (subprocess.TimeoutExpired, ProcessLookupError):
                self._process.kill()
                self._process.wait()
        self._reader.join(timeout=1)

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, *_: object) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass
